// src/pages/Login.jsx
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { login } from "../services/api";
import "./Login.css";

export default function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      await login(username, password);
      navigate("/dashboard");
    } catch (err) {
      setError(err.message || "Credenciales incorrectas");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-master">
      {/* GIF de fondo elegante */}
      <div className="gif-bg"></div>

      {/* Overlay negro elegante */}
      <div className="overlay-black"></div>

      <div className="login-box">
        <div className="logo-section">
          <h1 className="brand-name">AURUM</h1>
          <p className="tagline">Sistema de Gestión Premium</p>
        </div>

        <form onSubmit={handleSubmit} className="form">
          <input
            type="text"
            placeholder="USUARIO"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            className="input-gold"
          />
          <input
            type="password"
            placeholder="CONTRASEÑA"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="input-gold"
          />

          {error && <p className="error-msg">{error}</p>}

          <button type="submit" disabled={loading} className="btn-enter">
            {loading ? "VALIDANDO..." : "INGRESAR"}
          </button>
        </form>

        <p className="demo-text">
          Demo: <strong>admin</strong> / <strong>12345</strong>
        </p>
      </div>
    </div>
  );
}
